import json
import os
import shutil

from pyspark.sql import functions as F
from delta.tables import DeltaTable


def layout(path):
    # One row per month: the table's data files and their invoices, from the log. Don't change this.
    files = {}
    log = path + "/_delta_log/"
    for name in sorted(f for f in os.listdir(log) if f.endswith(".json")):
        with open(log + name) as f:
            for line in f:
                action = json.loads(line)
                if "add" in action:
                    add = action["add"]
                    files[add["path"]] = (add["partitionValues"].get("invoice_month"), json.loads(add["stats"])["numRecords"])
                if "remove" in action:
                    files.pop(action["remove"]["path"], None)
    by_value = {}
    for value, rows in files.values():
        by_value.setdefault(value, []).append(rows)
    return spark.createDataFrame(
        [(value, len(rows), sum(rows)) for value, rows in by_value.items()],
        "invoice_month STRING, files INT, invoices INT",
    )


def build_table(invoices, path):
    # Two loads, replayed on a fresh table: each writes one file per month. Don't change this.
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    monthly = invoices.select("*", F.date_format("invoice_date", "yyyy-MM").alias("invoice_month"))
    for load in range(2):
        monthly.coalesce(1).write.format("delta").mode("append").partitionBy("invoice_month").save(path)


def compact_closed_months(path):
    # Months before 2026 are closed: compact them, and leave 2026 alone.
    DeltaTable.forPath(spark, path).optimize().where("invoice_date < '2026-01-01'").executeCompaction()


def solve(invoices):
    path = "/tmp/billing/archive"
    build_table(invoices, path)
    compact_closed_months(path)
    return layout(path)
